BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"g":11,"uid":"9be25848-cd85-4641-91d9-16576256b298","n":1,"title":"الكفاية النحوية — إدارة الأعمال","track":"إدارة الأعمال","kind":"g11-1","context":"اجتمع فريق متجر طلابي لمراجعة السجلات المالية، ثم اقترح المدير تنظيم المهام.","key":"g11-1","skill":"تعيين العلاقات النحوية والإعراب في سياق وظيفي","ex":"في «راجعَ الفريقُ التقريرَ» يُعرب «الفريقُ» فاعلًا مرفوعًا و«التقريرَ» مفعولًا به منصوبًا. وفي «التقريرُ واضحٌ» مبتدأ وخبر مرفوعان. يبيّن تغير البنية وظيفة الكلمة لا مجرد موضعها من السطر.","q1":"ما إعراب «الفريقُ» في «راجع الفريق التقرير»؟","a1":"فاعل مرفوع","w1":["خبر مرفوع","مفعول به منصوب","مضاف إليه"],"q2":"ما إعراب «واضحٌ» في «التقرير واضح»؟","a2":"خبر مرفوع","w2":["فاعل","مفعول به","منادى"],"task":"أنشئ أربع جمل مرتبطة بمشروع مسارك وحدد الفاعل والمفعول به والمبتدأ والخبر بدقة. خصص المثال لمسار «إدارة الأعمال» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":11,"uid":"9be25848-cd85-4641-91d9-16576256b298","n":2,"title":"الكفاية الإملائية — إدارة الأعمال","track":"إدارة الأعمال","kind":"g11-2","context":"عُقد اجتماع لمناقشة جودة خدمة العملاء وتوزيع المسؤوليات.","key":"g11-2","skill":"توظيف همزات القطع والوصل وتحرير النص","ex":"همزة «أَحمد» همزة قطع تثبت في النطق عند الابتداء والوصل، وهمزة «استقبل» وصل في الفعل الماضي السداسي. يتحقق المدقق من بنية الكلمة ولا يغيّر شكل الهمزة لمجرد أن الحرف في أول السطر.","q1":"ما نوع الهمزة في «استقبل»؟","a1":"همزة وصل","w1":["همزة قطع","همزة متوسطة","همزة متطرفة"],"q2":"أي كلمة تبدأ بهمزة قطع؟","a2":"أحمد","w2":["استمع","اكتب","ابن"],"task":"راجع فقرة من إنشائك، وصنف ست كلمات بحسب نوع الهمزة مع تبرير رسمها. خصص المثال لمسار «إدارة الأعمال» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":11,"uid":"9be25848-cd85-4641-91d9-16576256b298","n":3,"title":"الكفاية القرائية — إدارة الأعمال","track":"إدارة الأعمال","kind":"g11-3","context":"ناقش زميلان تعبيرًا عن التعاون في مشروع اقتصادي صغير.","key":"g11-3","skill":"الفكرة الرئيسة والاستنتاج من دليل","ex":"نموذج قراءة مستقل: «ناقش الفريق مشروعًا جديدًا، ودوّن المخاطر، ثم اختبر تعديلًا قبل اعتماده». نستنتج أنه يتبع أسلوب مراجعة منظمة، لكن لا يجوز الجزم بأن المشروع نجح نهائيًا؛ فالنتيجة لم تذكر. هكذا نفصل ما يقوله النص عما نضيفه بالخيال.","q1":"ما الخطوة التي سبقت اعتماد التعديل في النص؟","a1":"اختباره أولًا","w1":["تجاهل المخاطر","حذف المراجعة","إعلان النتيجة قبل التجربة"],"q2":"أي استنتاج لا يثبته النص؟","a2":"أن المشروع حقق نجاحًا نهائيًا","w2":["أن الفريق ناقش المشروع","أن الفريق دوّن المخاطر","أن الفريق اختبر تعديلًا"],"task":"اقرأ فقرة جديدة واكتب حقيقتين صريحتين واستنتاجًا مبررًا وآخر غير مسنود واشرح الفرق. خصص المثال لمسار «إدارة الأعمال» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":11,"uid":"9be25848-cd85-4641-91d9-16576256b298","n":4,"title":"كفاية الاتصال الكتابي — إدارة الأعمال","track":"إدارة الأعمال","kind":"g11-4","context":"اجتمع فريق متجر طلابي لمراجعة السجلات المالية، ثم اقترح المدير تنظيم المهام.","key":"g11-4","skill":"تنظيم التقرير والرسالة بلغة دقيقة","ex":"يتضمن التقرير الوظيفي عنوانًا واضحًا وغاية محددة وإجراءً ونتيجة مع حدودها. في نموذج أصلي: «راجع الفريق خطة الأنشطة؛ فقارن ثلاث بدائل ثم اقترح موعدًا للتجربة». لا يصح في التقرير ادعاء نجاح خطة لم تُطبق بعد.","q1":"ما العنصر الذي يبين ما فعله الفريق في التقرير؟","a1":"وصف الإجراء","w1":["اسم الكاتب وحده","عنوان بلا مضمون","عبارة ثناء عامة"],"q2":"ما الصياغة الأنسب لنتيجة لم تختبر بعد؟","a2":"نقترح تجربة الخطة وقياس أثرها","w2":["نجحت الخطة بالتأكيد","لا حاجة للقياس","ثبتت جميع النتائج مسبقًا"],"task":"اكتب تقريرًا قصيرًا عن نشاط أو مشروع مع مقدمة وإجراء ونتيجة أو ملاحظة وحدود الدليل. خصص المثال لمسار «إدارة الأعمال» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":11,"uid":"9be25848-cd85-4641-91d9-16576256b298","n":5,"title":"كفاية التواصل الشفهي — إدارة الأعمال","track":"إدارة الأعمال","kind":"g11-5","context":"عُقد اجتماع لمناقشة جودة خدمة العملاء وتوزيع المسؤوليات.","key":"g11-5","skill":"الحوار المنظم وآداب الاستماع والحجة","ex":"في نقاش حول تخصيص وقت للتعلم يعرض متحدث حجته، ثم يعيد الثاني صياغة الفكرة قبل الاعتراض عليها، ويقترح الفريق معيارًا لاختبار الحل. لا تُقاس جودة المناقشة بارتفاع الصوت بل بدقة الاستماع ووضوح الأدلة.","q1":"ما الخطوة الأنسب قبل نقد رأي الزميل؟","a1":"إعادة صياغة رأيه بدقة","w1":["مقاطعته فورًا","الحكم على شخصه","تبديل الموضوع"],"q2":"كيف يمكن تقييم المقترح بعد النقاش؟","a2":"اختباره بمعيار واضح","w2":["الاكتفاء بكثرة التصفيق","رفض كل نقد","إخفاء النتائج"],"task":"قدم مناقشة قصيرة مع زميل، تتضمن رأيًا وحجة واعتراضًا مهذبًا وخلاصة قابلة للتقييم. خصص المثال لمسار «إدارة الأعمال» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":11,"uid":"9be25848-cd85-4641-91d9-16576256b298","n":6,"title":"الدراسات اللغوية — إدارة الأعمال","track":"إدارة الأعمال","kind":"g11-6","context":"ناقش زميلان تعبيرًا عن التعاون في مشروع اقتصادي صغير.","key":"g11-6","skill":"التمييز بين المعنى المعجمي والدلالة السياقية","ex":"قد تتغير دلالة كلمة «مفتاح» بحسب السياق: في «مفتاح الباب» أداة مادية، وفي «المراجعة مفتاح التحسن» استعمال مجازي يدل على الوسيلة. يعتمد فهم النص على القرينة وليس استخراج أول معنى من المعجم وحده.","q1":"ما دلالة «مفتاح» في «المراجعة مفتاح التحسن»؟","a1":"وسيلة مجازية لتحقيق التحسن","w1":["مفتاح معدني حقيقي","اسم شخص","إشارة إلى مكان محدد"],"q2":"ما الذي يعين على اختيار المعنى الصحيح؟","a2":"سياق الكلمة والقرائن","w2":["أول معنى معجمي دومًا","ترتيب السطر","عدد الحروف"],"task":"اختر ثلاث كلمات متعددة الدلالة واكتب لكل واحدة سياقين ومعنيين مختلفين. خصص المثال لمسار «إدارة الأعمال» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":11,"uid":"c31e1193-6169-41ba-b160-88602332bf98","n":1,"title":"الكفاية النحوية — الشرعي","track":"الشرعي","kind":"g11-1","context":"درس طالب معنى الأمانة في تعامل يومي مع كتاب مستعار، من دون اقتباس نص ديني.","key":"g11-1","skill":"تعيين العلاقات النحوية والإعراب في سياق وظيفي","ex":"في «راجعَ الفريقُ التقريرَ» يُعرب «الفريقُ» فاعلًا مرفوعًا و«التقريرَ» مفعولًا به منصوبًا. وفي «التقريرُ واضحٌ» مبتدأ وخبر مرفوعان. يبيّن تغير البنية وظيفة الكلمة لا مجرد موضعها من السطر.","q1":"ما إعراب «الفريقُ» في «راجع الفريق التقرير»؟","a1":"فاعل مرفوع","w1":["خب