تنتاج على اسم الحقبة وحده.","q1":"ما شرط نسبة سمة أدبية إلى فترة؟","a1":"تحليل شواهد مؤرخة وموثوقة","w1":["عنوان العصر فقط","اسم الشاعر وحده","تشابه قافية عارض"],"q2":"ما الذي يجب عدم تعميمه؟","a2":"أسلوب شاعر واحد على جميع كتاب عصره","w2":["أهمية سياق النص","ضرورة توثيق الشاهد","اختلاف النصوص"],"task":"اختر نصين صحيحَي النسبة من عصرين مختلفين، وقارن بين البناء والغرض مع مصدر لكل شاهد. خصص المثال لمسار «الصحة والحياة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"640f0f91-9ca0-4b9a-9a18-a48fea12a12b","n":2,"title":"تحليل النص الأدبي — الصحة والحياة","track":"الصحة والحياة","kind":"g12-2","context":"راجع فريق لوحة إرشادات صحية عامة قبل عرضها على زملائهم.","key":"g12-2","skill":"تحليل الفكرة والصورة وبنية النص الأدبي","ex":"في نص مستقل «عاد المسافر إلى المدينة، فأضاءت الذاكرة شوارعها القديمة»، لا تُفهم الإضاءة حرفيًا بل صورة مجازية لاستحضار الذكريات. نحدد الفكرة والعاطفة والتصوير، ثم نفحص كيف خدم التعبير معنى العودة.","q1":"ما الصورة في «أضاءت الذاكرة شوارعها»؟","a1":"إسناد الإضاءة إلى الذاكرة مجازًا","w1":["وصف مصباح حرفي","عملية حسابية","تحديد موعد الرحلة"],"q2":"ما العاطفة الأقرب لمشهد العودة والذكريات؟","a2":"الحنين","w2":["اللامبالاة","التهكم","الانتصار الرياضي"],"task":"حلل فقرة أدبية مأذونة الاستعمال من حيث الفكرة والصورة والعاطفة ووظيفة الكلمات. خصص المثال لمسار «الصحة والحياة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"640f0f91-9ca0-4b9a-9a18-a48fea12a12b","n":3,"title":"السياق والمدارس الأدبية — الصحة والحياة","track":"الصحة والحياة","kind":"g12-3","context":"قارن طالب طريقة صياغة خبر صحي بمقال يوضح أهمية التحقق من المصادر.","key":"g12-3","skill":"التمييز بين المدرسة الأدبية والسياق الفردي","ex":"قد تتقاطع خصائص الكلاسيكية والرومنسية والواقعية في تاريخ الأدب، ولا يصح تصنيف كل نص يتحدث عن الطبيعة باعتباره رومنسيًا. نعتمد بنية النص وعلاقته بالتجربة الذاتية أو القضايا الاجتماعية وسياقه المؤرخ.","q1":"ما الدليل الأفضل لتحديد مدرسة أدبية؟","a1":"شواهد أسلوبية وموضوعية في سياق موثق","w1":["اسم الشاعر وحده","العنوان وحده","سنة الطباعة فقط"],"q2":"هل ذكر الطبيعة وحده يكفي للحكم بالرومنسية؟","a2":"لا، يلزم تحليل البناء والتجربة والسياق","w2":["نعم في كل الحالات","نعم إذا زادت الأبيات","نعم مهما كان الغرض"],"task":"قارن نصين صحيحَي النسبة يظهران اتجاهين أدبيين وناقش ما يدعم التصنيف وما يحده. خصص المثال لمسار «الصحة والحياة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"640f0f91-9ca0-4b9a-9a18-a48fea12a12b","n":4,"title":"التذوق والنقد الأدبي — الصحة والحياة","track":"الصحة والحياة","kind":"g12-4","context":"نظمت مجموعة توعية مدرسية حملة لتعزيز العادات اليومية السليمة دون تقديم نصائح طبية فردية.","key":"g12-4","skill":"إسناد الحكم النقدي إلى شاهد فني","ex":"يقول ناقد متخيل «الصورة ناجحة لأنها تربط الإحساس بالوصف»، ثم يحدد عبارة «هدأ الليل فوق البيوت» ويفسر أثرها في إبطاء الإيقاع. أما القول «النص جميل جدًا» دون شاهد فهو رأي لا يقوم مقام التحليل. لا ينبغي اختلاق بيت لشاعر تاريخي في أثناء التذوق.","q1":"أي حكم نقدي أكثر استنادًا للدليل؟","a1":"الصورة تعزز الهدوء بتشخيص الليل وبيان أثره","w1":["هذا أجمل نص بلا منازع","كل القراء سيعجبون به","العنوان وحده يثبت الجودة"],"q2":"ما الخطوة التي تسبق تقييم الصورة؟","a2":"تحديدها من النص وشرح علاقتها بالمعنى","w2":["تخمين اسم المؤلف","حذف السياق","الاكتفاء بعد الكلمات"],"task":"اكتب حكمين نقديين بشأن فقرة من إنشائك مع شاهد وسبب، واقترح قراءة بديلة. خصص المثال لمسار «الصحة والحياة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"65d8f501-563d-435c-8e93-b5d504a2c02e","n":1,"title":"الأدب العربي وتاريخه — العام","track":"العام","kind":"g12-1","context":"نظم فريق تطوعي جدولًا لزيارة المكتبة ومناقشة مهارات القراءة.","key":"g12-1","skill":"الربط بين الإنتاج الأدبي وسياقه الزمني","ex":"تاريخ الأدب دراسة تحول الأجناس والأساليب وعلاقتها بالبيئة دون افتراض أن جميع شعراء العصر الواحد يتشابهون. يقارن المتعلم نصين مؤرخين من مصدرين موثوقين في الموضوع والبناء ونبرة المخاطب. لا يعتمد الاستنتاج على اسم الحقبة وحده.","q1":"ما شرط نسبة سمة أدبية إلى فترة؟","a1":"تحليل شواهد مؤرخة وموثوقة","w1":["عنوان العصر فقط","اسم الشاعر وحده","تشابه قافية عارض"],"q2":"ما الذي يجب عدم تعميمه؟","a2":"أسلوب شاعر واحد على جميع كتاب عصره","w2":["أهمية سياق النص","ضرورة توثيق الشاهد","اختلاف النصوص"],"task":"اختر نصين صحيحَي النسبة من عصرين مختلفين، وقارن بين البناء والغرض مع مصدر لكل شاهد. خصص المثال لمسار «العام» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"65d8f501-563d-435c-8e93-b5d504a2c02e","n":2,"title":"تحليل النص الأدبي — العام","track":"العام","kind":"g12-2","context":"استعدت طالبة لعرض تجربة مدرسية، وقارنت بين تفسيرين مدعومين بدليل.","key":"g12-2","skill":"تحليل الفكرة والصورة وبنية النص الأدبي","ex":"في نص مستقل «عاد المسافر إلى المدينة، فأضاءت الذاكرة شوارعها القديمة»، لا تُفهم الإضاءة حرفيًا بل صورة مجازية لاستحضار الذكريات. نحدد الفكرة والعاطفة والتصوير، ثم نفحص كيف خدم التعبير معنى العودة.","q1":"ما الصورة في «أضاءت الذاكرة شوارعها»؟","a1":"إسناد الإضاءة إلى الذاكرة مجازًا","w1":["وصف مصباح حرفي","عملية حسابية","تحديد موعد الرحلة"],"q2":"ما العاطفة الأقرب لمشهد العودة والذكريات؟","a2":"الحنين","w2":["اللامبالاة","التهكم","الانتصار الرياضي"],"task":"حلل فقرة أدبية مأذونة الاستعمال من حيث الفكرة والصورة والعاطفة ووظيفة الكلمات. خصص المثال لمسار «العام» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"65d8f501-563d-435c-8e93-b5d504a2c02e","n":3,"title":"السياق والمدارس الأدبية — العام","track":"العام","kind":"g12-3","context":"راجع نادي المدرسة إعلان نشاط عام وحدد فكرته ومخاطبيه.","key":"g12-3","skill":"التمييز بين المدرسة الأدبية والسياق الفردي","ex":"قد تتقاطع خصائص الكلاسيكية والرومنسية والواقعية في تاريخ الأدب، ولا يصح تصنيف كل نص يتحدث عن الطبيعة باعتباره رومنسيًا. نعتمد بنية النص وعلاقته بالتجربة الذاتية أو القضايا الاجتماعية وسياقه المؤرخ.","q1":"ما الدليل الأفضل لتحديد مدرسة أدبية؟","a1":"شواهد أسلوبية وموضوعية في سياق موثق","w1":["اسم الشاعر وحده","العنوان وحده","سنة الطباعة فقط"],"q2":"هل ذكر الطبيعة وحده يكفي للحكم بالرومنسية؟","a2":"لا، يلزم تحليل البناء والتجربة والسياق","w2":["نعم في كل الحالات","نعم إذا زادت الأبيات","نعم مهما كان الغرض"],"task":"قارن نصين صحيحَي النسبة يظهران اتجاهين أدبيين وناقش ما يدعم التصنيف وما يحده. خصص المثال لمسار «العام» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"65d8f501-563d-435c-8e93-b5d504a2c02e","n":4,"title":"التذوق والنقد الأدبي — العام","track":"العام","kind":"g12-4","context":"نظم فريق تطوعي جدولًا لزيارة المكتبة ومناقشة مهارات القراءة.","key":"g12-4","skill":"إسناد الحكم النقدي إلى شاهد فني","ex":"يقول ناقد متخيل «الصورة ناجحة لأنها تربط الإحساس بالوصف»، ثم يحدد عبارة «هدأ الليل فوق البيوت» ويفسر أثرها في إبطاء الإيقاع. أما القول «النص جميل جدًا» دون شاهد فهو رأي لا يقوم مقام التحليل. لا ينبغي اختلاق بيت لشاعر تاريخي في أثناء التذوق.","q1":"أي حكم نقدي أكثر استنادًا للدليل؟","a1":"الصورة تعزز الهدوء بتشخيص الليل وبيان أثره","w1":["هذا أجمل نص بلا منازع","كل القراء سيعجبون به","العنوان وحده يثبت الجودة"],"q2":"ما الخطوة التي تسبق تقييم الصورة؟","a2":"تحديدها من النص وشرح علاقتها بالمعنى","w2":["تخمين اسم المؤلف","حذف السياق","الاكتفاء بعد الكلمات"],"task":"اكتب حكمين نقديين بشأن فقرة من إنشائك مع شاهد وسبب، واقترح قراءة بديلة. خصص المثال لمسار «العام» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"65d8f501-563d-435c-8e93-b5d504a2c02e","n":5,"title":"الكتابة الوظيفية والإبداعية — مجال اختياري","track":"العام","kind":"g12-5-optional","context":"استعدت طالبة لعرض تجربة مدرسية، وقارنت بين تفسيرين مدعومين بدليل.","key":"g12-5-optional","skill":"التمييز بين الرسالة الوظيفية والمشهد الإبداعي","ex":"الرسالة الوظيفية تطلب عملًا محددًا بمعلومات مرتبة ولغة مناسبة، أما النص الإبداعي فيبني تجربة أو شخصية وصورة فنية. مثال مستقل: طلب إداري لتخصيص قاعة مقابل مشهد قصصي يصف طالبًا يستعد للاجتماع.","q1":"أي عنصر أساسي في الرسالة الوظيفية؟","a1":"الطلب الواضح والمعلومات اللازمة","w1":["إخفاء الغرض","اختراع شخصية دائمًا","إهمال المخاطب"],"q2":"أي عنصر يخدم النص الإبداعي أكثر؟","a2":"التصوير والشخصية وتطور الحدث","w2":["التوقيع الإداري فقط","خانة الموضوع وحدها","بيانات المرسل الرسمية"],"task":"اكتب رسالة طلب ومشهدًا إبداعيًا قصيرًا عن الموضوع نفسه، ثم وضح اختلاف الهدف واللغة. خصص المثال لمسار «العام» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"c3df9b43-e37e-45af-b2f5-dc7e19f75a09","n":1,"title":"الأدب العربي وتاريخه — علوم الحاسب والهندسة","track":"علوم الحاسب والهندسة","kind":"g12-1","context":"ناقش فريق تقني توثيق خطوات مشروع رقمي ومراجعة ما يمكن إثباته.","key":"g12-1","skill":"الربط بين الإنتاج الأدبي وسياقه الزمني","ex":"تاريخ الأدب دراسة تحول الأجناس والأساليب وعلاقتها بالبيئة دون افتراض أن جميع شعراء العصر الواحد يتشابهون. يقارن المتعلم نصين مؤرخين من مصدرين موثوقين في الموضوع والبناء ونبرة المخاطب. لا يعتمد الاستنتاج على اسم الحقبة وحده.","q1":"ما شرط نسبة سمة أدبية إلى فترة؟","a1":"تحليل شواهد مؤرخة وموثوقة","w1":["عنوان العصر فقط","اسم الشاعر وحده","تشابه قافية عارض"],"q2":"ما الذي يجب عدم تعميمه؟","a2":"أسلوب شاعر واحد على جميع كتاب عصره","w2":["أهمية سياق النص","ضرورة توثيق الشاهد","اختلاف النصوص"],"task":"اختر نصين صحيحَي النسبة من عصرين مختلفين، وقارن بين البناء والغرض مع مصدر لكل شاهد. خصص المثال لمسار «علوم الحاسب والهندسة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"c3df9b43-e37e-45af-b2f5-dc7e19f75a09","n":2,"title":"تحليل النص الأدبي — علوم الحاسب والهندسة","track":"علوم الحاسب والهندسة","kind":"g12-2","context":"أنشأ الطلاب نموذجًا أوليًا لتطبيق ثم كتبوا تقريرًا يصف النتيجة وحدودها.","key":"g12-2","skill":"تحليل الفكرة والصورة وبنية النص الأدبي","ex":"في نص مستقل «عاد المسافر إلى المدينة، فأضاءت الذاكرة شوارعها القديمة»، لا تُفهم الإضاءة حرفيًا بل صورة مجازية لاستحضار الذكريات. نحدد الفكرة والعاطفة والتصوير، ثم نفحص كيف خدم التعبير معنى العودة.","q1":"ما الصورة في «أضاءت الذاكرة شوارعها»؟","a1":"إسناد الإضاءة إلى الذاكرة مجازًا","w1":["وصف مصباح حرفي","عملية حسابية","تحديد موعد الرحلة"],"q2":"ما العاطفة الأقرب لمشهد العودة والذكريات؟","a2":"الحنين","w2":["اللامبالاة","التهكم","الانتصار الرياضي"],"task":"حلل فقرة أدبية مأذونة الاستعمال من حيث الفكرة والصورة والعاطفة ووظيفة الكلمات. خصص المثال لمسار «علوم الحاسب والهندسة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"c3df9b43-e37e-45af-b2f5-dc7e19f75a09","n":3,"title":"السياق والمدارس الأدبية — علوم الحاسب والهندسة","track":"علوم الحاسب والهندسة","kind":"g12-3","context":"قارن فريق تصميم بين وصفين لحل مشكلة دون الادعاء بنجاح غير مجرَّب.","key":"g12-3","skill":"التمييز بين المدرسة الأدبية والسياق الفردي","ex":"قد تتقاطع خصائص الكلاسيكية والرومنسية والواقعية في تاريخ الأدب، ولا يصح تصنيف كل نص يتحدث عن الطبيعة باعتباره رومنسيًا. نعتمد بنية النص وعلاقته بالتجربة الذاتية أو القضايا الاجتماعية وسياقه المؤرخ.","q1":"ما الدليل الأفضل لتحديد مدرسة أدبية؟","a1":"شواهد أسلوبية وموضوعية في سياق موثق","w1":["اسم الشاعر وحده","العنوان وحده","سنة الطباعة فقط"],"q2":"هل ذكر الطبيعة وحده يكفي للحكم بالرومنسية؟","a2":"لا، يلزم تحليل البناء والتجربة والسياق","w2":["نعم في كل الحالات","نعم إذا زادت الأبيات","نعم مهما كان الغرض"],"task":"قارن نصين صحيحَي النسبة يظهران اتجاهين أدبيين وناقش ما يدعم التصنيف وما يحده. خصص المثال لمسار «علوم الحاسب والهندسة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."},{"g":12,"uid":"c3df9b43-e37e-45af-b2f5-dc7e19f75a09","n":4,"title":"التذوق والنقد الأدبي — علوم الحاسب والهندسة","track":"علوم الحاسب والهندسة","kind":"g12-4","context":"ناقش فريق تقني توثيق خطوات مشروع رقمي ومراجعة ما يمكن إثباته.","key":"g12-4","skill":"إسناد الحكم النقدي إلى شاهد فني","ex":"يقول ناقد متخيل «الصورة ناجحة لأنها تربط الإحساس بالوصف»، ثم يحدد عبارة «هدأ الليل فوق البيوت» ويفسر أثرها في إبطاء الإيقاع. أما القول «النص جميل جدًا» دون شاهد فهو رأي لا يقوم مقام التحليل. لا ينبغي اختلاق بيت لشاعر تاريخي في أثناء التذوق.","q1":"أي حكم نقدي أكثر استنادًا للدليل؟","a1":"الصورة تعزز الهدوء بتشخيص الليل وبيان أثره","w1":["هذا أجمل نص بلا منازع","كل القراء سيعجبون به","العنوان وحده يثبت الجودة"],"q2":"ما الخطوة التي تسبق تقييم الصورة؟","a2":"تحديدها من النص وشرح علاقتها بالمعنى","w2":["تخمين اسم المؤلف","حذف السياق","الاكتفاء بعد الكلمات"],"task":"اكتب حكمين نقديين بشأن فقرة من إنشائك مع شاهد وسبب، واقترح قراءة بديلة. خصص المثال لمسار «علوم الحاسب والهندسة» من خلال موقف أصلي غير منسوب إلى مقرر رسمي."}]'::jsonb)
 AS x(g integer,uid uuid,n integer,title text,track text,kind text,
      context text,key text,skill text,ex text,q1 text,a1 text,w1 text[],
      q2 text,a2 text,w2 text[],task text)
 LOOP
   SELECT l.id,l.content INTO STRICT target_id,previous_content FROM public.lessons l
   JOIN public.units u ON u.id=l.unit_id
   JOIN public.grades g ON g.id=u.grade_id
   JOIN public.curricula cu ON cu.id=g.curriculum_id
   JOIN public.countries co ON co.id=cu.country_id
   WHERE co.code='SA' AND cu.id='f42518c1-c7bd-45da-bb37-69cf9eca0a56'::uuid
    AND g.grade_number=r.g AND u.id=r.uid AND u.semester IS NULL
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
   FOR UPDATE OF l;

   SELECT count(*) INTO attempts FROM public.student_lesson_progress
      WHERE lesson_id=target_id;
   IF attempts<>0 THEN RAISE EXCEPTION 'SA_TRACK_LEARNER_PROGRESS_%',r.title; END IF;
   SELECT count(*) INTO attempts FROM public.lesson_activity_attempts att
      JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
   IF attempts<>0 THEN RAISE EXCEPTION 'SA_TRACK_ACTIVITY_ATTEMPTS_%',r.title; END IF;
   SELECT count(*) INTO count_rows FROM public.lesson_activities
      WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
   IF count_rows<>3 OR coalesce(previous_content,'') LIKE '%DADYOOM_SA_SECONDARY_TRACKS_ORIGINAL_52_20261009%' THEN
      RAISE EXCEPTION 'SA_TRACK_NOT_UNTOUCHED_PLACEHOLDER_%',r.title;
   END IF;

   UPDATE public.lessons SET
    content='ضاديوم — إثراء أصلي مستقل لمسار «'||r.track||'» بالصف '||r.g::text||
       ' السعودي. المحتوى أمثلة من ضاديوم وليس اقتباسًا رسميًا، ولم نتحقق من الكتاب/الفصل الدراسي المعتمد لهذا المسار.'
       ||E'\n\n'||'المهارة: '||r.skill
       ||E'\n\n'||'موقف تمهيدي من سياق المسار: '||r.context
       ||E'\n\n'||'شرح أصلي وتطبيق: '||r.ex
       ||E'\n\n'||'سؤال للتحقق: '||r.q1
       ||E'\n\n'||'سؤال تطبيق آخر: '||r.q2
       ||E'\n\n'||'تكليف التمايز: '||r.task
       ||E'\n\n'||'للطلاب المحتاجين للدعم: مثال محلول وتحديد المفردات. للمتقدمين: تفسير بديل ومراجعة الشواهد. أي إنتاج مفتوح يخضع لمراجعة المعلم.'
       ||E'\n\n'||'مرجع العنوان المستورد السابق: '||coalesce(previous_content,''),
       updated_at=now()
    WHERE id=target_id;

   UPDATE public.lesson_activities SET prompt=r.q1,
    content=content||jsonb_build_object('origin','DADYOOM_SA_SECONDARY_TRACKS_ORIGINAL_52_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
      'text',r.q1,'notOfficialBook',true,'sourceVerification','pending',
      'options',CASE ((r.n+r.g)%4)
       WHEN 0 THEN jsonb_build_array(r.a1,r.w1[1],r.w1[2],r.w1[3])
       WHEN 1 THEN jsonb_build_array(r.w1[1],r.a1,r.w1[2],r.w1[3])
       WHEN 2 THEN jsonb_build_array(r.w1[1],r.w1[2],r.a1,r.w1[3])
       ELSE jsonb_build_array(r.w1[1],r.w1[2],r.w1[3],r.a1) END),
    answer=jsonb_build_object('correct',r.a1)
    WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice'
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

   UPDATE public.lesson_activities SET prompt=r.q2,
    content=content||jsonb_build_object('origin','DADYOOM_SA_SECONDARY_TRACKS_ORIGINAL_52_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
      'text',r.q2,'notOfficialBook',true,'sourceVerification','pending',
      'options',CASE ((r.n+r.g+1)%4)
       WHEN 0 THEN jsonb_build_array(r.a2,r.w2[1],r.w2[2],r.w2[3])
       WHEN 1 THEN jsonb_build_array(r.w2[1],r.a2,r.w2[2],r.w2[3])
       WHEN 2 THEN jsonb_build_array(r.w2[1],r.w2[2],r.a2,r.w2[3])
       ELSE jsonb_build_array(r.w2[1],r.w2[2],r.w2[3],r.a2) END),
    answer=jsonb_build_object('correct',r.a2)
    WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice'
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

   UPDATE public.lesson_activities SET
     prompt=CASE WHEN r.g=11 AND r.n=3 THEN
          'اقرأ النص المستقل ثم حدد فكرة وقرينة واستنتاجًا صحيحًا.'
       WHEN r.g=11 AND r.n=5 THEN
          'قدم مناقشة شفهية من دقيقة مع أدلة واستماع واحترام للمخاطب.'
       WHEN r.g=12 AND (r.n<=4 OR r.n>=5 AND r.track<>'العام') THEN
          'اقرأ المثال الأدبي المستقل واستخرج الصورة والحجة ثم ناقش تفسيرًا محتملًا.'
       ELSE r.task END,
     content=content||jsonb_build_object('origin','DADYOOM_SA_SECONDARY_TRACKS_ORIGINAL_52_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
       'text',r.task,'notOfficialBook',true,'humanReviewRequired',true,
       'sourceVerification','pending')
     WHERE lesson_id=target_id AND activity_order=3
       AND activity_type=CASE
         WHEN r.g=11 AND r.n=3 THEN 'reading'
         WHEN r.g=11 AND r.n=5 THEN 'speaking'
         WHEN r.g=12 AND r.track='العام' AND r.n=5 THEN 'writing'
         WHEN r.g=12 THEN 'reading'
         ELSE 'writing' END
       AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';

   SELECT count(*) INTO count_rows FROM public.lesson_activities
     WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_SECONDARY_TRACKS_ORIGINAL_52_20261009';
   IF count_rows<>3 THEN RAISE EXCEPTION 'SA_TRACK_ACTIVITY_UPDATE_FAILED_%_COUNT_%',r.title,count_rows; END IF;
 END LOOP;
END $dadyoom$;